export const title = "How to Check a USB Hub When Your Webcam or Microphone Disconnects";
export const metaTitle = "Why Your Webcam or Mic Disconnects on a Hub";
export const metaDescription = "Isolate webcam and microphone USB problems with a direct baseline, one-device changes, and a documented connection map. A research-based guide from DeskFinds.";
export const author = "Jamie Cole, Lead Product Researcher";
